BEGIN;
CREATE TABLE public.school_system_role_permissions (
 school_id uuid NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE,
 role public.app_role NOT NULL CHECK(role NOT IN ('super_admin','school_owner')),
 module text NOT NULL CHECK(module IN ('students','admissions','classes','fees','expenses','student_attendance','staff_attendance','employees','inventory','assets','tasks','cases','reports','settings','users')),
 can_view boolean NOT NULL, can_create boolean NOT NULL, can_edit boolean NOT NULL, can_manage boolean NOT NULL,
 PRIMARY KEY(school_id,role,module), CHECK(can_view OR NOT(can_create OR can_edit OR can_manage)), CHECK(NOT can_manage OR (can_create AND can_edit))
);
ALTER TABLE public.school_system_role_permissions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.school_system_role_permissions FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.school_system_role_permissions TO authenticated;
GRANT ALL ON public.school_system_role_permissions TO service_role;
CREATE POLICY "Members read school system matrix" ON public.school_system_role_permissions FOR SELECT TO authenticated USING(public.is_school_member(auth.uid(),school_id) OR public.is_super_admin(auth.uid()));
