e,"can_create":false,"can_edit":false,"can_manage":false},"classes":{"module":"classes","can_view":true,"can_create":false,"can_edit":false,"can_manage":false},"fees":{"module":"fees","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"expenses":{"module":"expenses","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"student_attendance":{"module":"student_attendance","can_view":true,"can_create":true,"can_edit":true,"can_manage":false},"staff_attendance":{"module":"staff_attendance","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"employees":{"module":"employees","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"inventory":{"module":"inventory","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"assets":{"module":"assets","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"tasks":{"module":"tasks","can_view":true,"can_create":false,"can_edit":true,"can_manage":false},"cases":{"module":"cases","can_view":true,"can_create":true,"can_edit":true,"can_manage":false},"reports":{"module":"reports","can_view":true,"can_create":false,"can_edit":false,"can_manage":false},"settings":{"module":"settings","can_view":true,"can_create":false,"can_edit":false,"can_manage":false},"users":{"module":"users","can_view":false,"can_create":false,"can_edit":false,"can_manage":false}},"store_keeper":{"students":{"module":"students","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"admissions":{"module":"admissions","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"classes":{"module":"classes","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"fees":{"module":"fees","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"expenses":{"module":"expenses","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"student_attendance":{"module":"student_attendance","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"staff_attendance":{"module":"staff_attendance","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"employees":{"module":"employees","can_view":false,"can_create":false,"can_edit":false,"can_manage":false},"inventory":{"module":"inventory","can_view":true,"can_create":true,"can_edit":true,"can_manage":true},"assets":{"module":"assets","can_view":true,"can_create":true,"can_edit":true,"can_manage":true},"tasks":{"module":"tasks","can_view":true,"can_create":true,"can_edit":true,"can_manage":true},"cases":{"module":"cases","can_view":true,"can_create":false,"can_edit":true,"can_manage":false},"reports":{"module":"reports","can_view":true,"can_create":false,"can_edit":false,"can_manage":false},"settings":{"module":"settings","can_view":true,"can_create":false,"can_edit":false,"can_manage":false},"users":{"module":"users","can_view":false,"can_create":false,"can_edit":false,"can_manage":false}}}'::jsonb -> _role::text -> _module ->> ('can_'||_action))::boolean,false);
