REVOKE ALL ON FUNCTION private.default_role_permission(public.app_role,text,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.has_system_module_permission(_user_id uuid,_school_id uuid,_module text,_action text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT public.is_super_admin(_user_id) OR (public.is_school_member(_user_id,_school_id) AND (
 public.has_role(_user_id,_school_id,'school_owner') OR EXISTS (
 SELECT 1 FROM public.user_roles r LEFT JOIN public.school_system_role_permissions p ON p.school_id=r.school_id AND p.role=r.role AND p.module=_module
 WHERE r.school_id=_school_id AND r.user_id=_user_id AND coalesce(CASE _action WHEN 'view' THEN p.can_view WHEN 'create' THEN p.can_create WHEN 'edit' THEN p.can_edit WHEN 'manage' THEN p.can_manage END,private.default_role_permission(r.role,_module,_action))
 )));
$$;
REVOKE ALL ON FUNCTION public.has_system_module_permission(uuid,uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_system_module_permission(uuid,uuid,text,text) TO authenticated;
-- Keep legacy row scopes. Only explicit NEW system grants supplement old policies.
CREATE OR REPLACE FUNCTION public.has_custom_module_permission(_user_id uuid,_school_id uuid,_module text,_action text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT public.is_school_member(_user_id,_school_id) AND (
 EXISTS(SELECT 1 FROM public.school_user_custom_roles a JOIN public.school_roles r ON r.id=a.role_id AND r.school_id=a.school_id AND r.is_active
 JOIN public.school_role_permissions p ON p.role_id=r.id AND p.school_id=r.school_id WHERE a.user_id=_user_id AND a.school_id=_school_id AND p.module=_module AND
 CASE _action WHEN 'view' THEN p.can_view WHEN 'create' THEN p.can_create WHEN 'edit' THEN p.can_edit WHEN 'manage' THEN p.can_manage ELSE false END)
 OR EXISTS(SELECT 1 FROM public.user_roles r JOIN public.school_system_role_permissions p ON p.school_id=r.school_id AND p.role=r.role
 WHERE r.user_id=_user_id AND r.school_id=_school_id AND p.module=_module AND NOT private.default_role_permission(r.role,_module,_action) AND
 CASE _action WHEN 'view' THEN p.can_view WHEN 'create' THEN p.can_create WHEN 'edit' THEN p.can_edit WHEN 'manage' THEN p.can_manage ELSE false END));
$$;
CREATE FUNCTION private.system_override_guard(_user_id uuid,_school_id uuid,_module text,_action text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT public.is_super_admin(_user_id) OR public.has_role(_user_id,_school_id,'school_owner') OR
 NOT EXISTS(SELECT 1 FROM public.school_system_role_permissions p JOIN public.user_roles r ON r.school_id=p.school_id AND r.role=p.role WHERE r.user_id=_user_id AND r.school_id=_school_id AND p.module=_module)
 OR public.has_system_module_permission(_user_id,_school_id,_module,_action) OR public.has_custom_module_permission(_user_id,_school_id,_module,_action);
$$;
REVOKE ALL ON FUNCTION private.system_override_guard(uuid,uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.system_override_guard(uuid,uuid,text,text) TO authenticated;
CREATE FUNCTION public.settings_my_system_permissions(_school_id uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce(jsonb_object_agg(module,jsonb_build_object('view',public.has_system_module_permission(auth.uid(),_school_id,module,'view'),'create',public.has_system_module_permission(auth.uid(),_school_id,module,'create'),'edit',public.has_system_module_permission(auth.uid(),_school_id,module,'edit'),'manage',public.has_system_module_permission(auth.uid(),_school_id,module,'manage'))),'{}')
 FROM (SELECT DISTINCT p.module FROM public.school_system_role_permissions p JOIN public.user_roles r ON r.school_id=p.school_id AND r.role=p.role WHERE r.user_id=auth.uid() AND r.school_id=_school_id AND public.is_school_member(auth.uid(),_school_id)) m;
$$;
REVOKE ALL ON FUNCTION public.settings_my_system_permissions(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.settings_my_system_permissions(uuid) TO authenticated;
CREATE FUNCTION public.settings_save_system_role(_school_id uuid,_role public.app_role,_permissions jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE entry jsonb;
BEGIN
 PERFORM 1 FROM public.schools WHERE id=_school_id FOR UPDATE;
 IF NOT public.can_manage_school(auth.uid(),_school_id) THEN RAISE EXCEPTION 'School management permission required' USING ERRCODE='42501'; END IF;
 IF _role IS NULL OR _role IN ('super_admin','school_owner') THEN RAISE EXCEPTION 'Protected role cannot be customized'; END IF;
 IF _role='school_manager' AND NOT(public.has_role(auth.uid(),_school_id,'school_owner') OR public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'Only owner can customize school managers'; END IF;
 IF _permissions IS NULL OR jsonb_typeof(_permissions)<>'array' OR jsonb_array_length(_permissions)<>15 THEN RAISE EXCEPTION 'Complete permission matrix required'; END IF;
 DELETE FROM public.school_system_role_permissions WHERE school_id=_school_id AND role=_role;
 FOR entry IN SELECT value FROM jsonb_array_elements(_permissions) LOOP
  IF entry->>'module' IN ('settings','users') AND EXISTS(SELECT 1 FROM unnest(ARRAY['view','create','edit','manage']) a WHERE (entry->>('can_'||a))::boolean IS DISTINCT FROM private.default_role_permission(_role,entry->>'module',a)) THEN RAISE EXCEPTION 'Administrative role scope is protected'; END IF;
  INSERT INTO public.school_system_role_permissions(school_id,role,module,can_view,can_create,can_edit,can_manage)
  VALUES(_school_id,_role,entry->>'module',(entry->>'can_view')::boolean,(entry->>'can_create')::boolean,(entry->>'can_edit')::boolean,(entry->>'can_manage')::boolean);
 END LOOP;
 INSERT INTO public.audit_logs(school_id,user_id,action,entity_type,metadata) VALUES(_school_id,auth.uid(),'update','school_system_role',jsonb_build_object('role',_role));
END $$;
REVOKE ALL ON FUNCTION public.settings_save_system_role(uuid,public.app_role,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.settings_save_system_role(uuid,public.app_role,jsonb) TO authenticated;
-- Restrictive policies narrow existing permissions and cannot grant cross-tenant access.
DO $$
DECLARE r record; a text; command text; predicate text;
BEGIN
 FOR r IN SELECT * FROM (VALUES
 ('students','students'),('guardians','students'),('student_guardians','students'),('student_enrollments','students'),('student_documents','students'),('admission_applications','admissions'),('stages','classes'),('grades','classes'),('sections','classes'),
 ('fee_categories','fees'),('fee_structures','fees'),('student_fees','fees'),('installment_plans','fees'),('installments','fees'),('discounts','fees'),('payments','fees'),('payment_allocations','fees'),('expense_categories','expenses'),('cost_centers','expenses'),('expenses','expenses'),('departments','employees'),('employees','employees'),
 ('student_attendance','student_attendance'),('staff_attendance','staff_attendance'),('inventory_categories','inventory'),('inventory_items','inventory'),('inventory_movements','inventory'),('asset_categories','assets'),('assets','assets'),('asset_history','assets'),('tasks','tasks'),('task_comments','tasks'),('cases','cases'),('case_comments','cases'),('school_settings','settings')
 ) AS modules(table_name,module) LOOP
  FOREACH a IN ARRAY ARRAY['view','create','edit','manage'] LOOP
   command:=CASE a WHEN 'view' THEN 'SELECT' WHEN 'create' THEN 'INSERT' WHEN 'edit' THEN 'UPDATE' ELSE 'DELETE' END;
   predicate:=format('private.system_override_guard(auth.uid(),school_id,%L,%L)',r.module,a);
   EXECUTE format('CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR %s TO authenticated %s','System matrix '||a,r.table_name,command,CASE command WHEN 'INSERT' THEN 'WITH CHECK ('||predicate||')' WHEN 'UPDATE' THEN 'USING ('||predicate||') WITH CHECK ('||predicate||')' ELSE 'USING ('||predicate||')' END);
  END LOOP;
 END LOOP;
END $$;
CREATE POLICY "System matrix files read" ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id NOT IN ('student-documents','finance-attachments') OR private.system_override_guard(auth.uid(),((storage.foldername(name))[1])::uuid,CASE bucket_id WHEN 'student-documents' THEN 'students' ELSE 'expenses' END,'view'));
CREATE POLICY "System matrix files insert" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id NOT IN ('student-documents','finance-attachments') OR private.system_override_guard(auth.uid(),((storage.foldername(name))[1])::uuid,CASE bucket_id WHEN 'student-documents' THEN 'students' ELSE 'expenses' END,'create'));
CREATE POLICY "System matrix files delete" ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id NOT IN ('student-documents','finance-attachments') OR private.system_override_guard(auth.uid(),((storage.foldername(name))[1])::uuid,CASE bucket_id WHEN 'student-documents' THEN 'students' ELSE 'expenses' END,'manage'));
-- Definer operations receive matching action guards; abort on unexpected schema drift.
DO $$
DECLARE r record; definition text; patched text;
BEGIN
 FOR r IN SELECT * FROM (VALUES
 ('refresh_finance_statuses','public.can_view_finance(auth.uid(), _school_id)','fees','view','_school_id'),('set_installment_plan','public.can_manage_finance(auth.uid(), fee.school_id)','fees','edit','fee.school_id'),('add_discount','public.can_manage_finance(auth.uid(), fee.school_id)','fees','create','fee.school_id'),('deactivate_discount','public.can_manage_finance(auth.uid(), d.school_id)','fees','manage','d.school_id'),('record_payment','public.can_manage_finance(auth.uid(), st.school_id)','fees','create','st.school_id'),('cancel_payment','public.can_manage_finance(auth.uid(), p.school_id)','fees','manage','p.school_id'),('apply_fee_structure','public.can_manage_finance(auth.uid(), fs.school_id)','fees','create','fs.school_id'),('record_asset_event','private.can_manage_assets(current_asset.school_id)','assets','manage','current_asset.school_id'),('task_before_write','private.can_manage_tasks(NEW.school_id)','tasks','create','NEW.school_id'),('task_before_write','private.can_manage_tasks(OLD.school_id)','tasks','edit','OLD.school_id'),('case_before_write','private.can_scope_case(NEW.school_id,NEW.student_id,NEW.guardian_id,NEW.employee_id)','cases','create','NEW.school_id'),('case_before_write','private.can_scope_case(OLD.school_id,OLD.student_id,OLD.guardian_id,OLD.employee_id)','cases','edit','OLD.school_id'),('task_comment_before_write','private.can_view_task(t.school_id,t.assigned_to_user_id)','tasks','create','t.school_id'),('case_comment_before_write','private.can_view_case(c.school_id,c.student_id,c.guardian_id,c.employee_id,c.assigned_to_user_id)','cases','create','c.school_id')
 ) AS guards(name,old_guard,module,action,school_expression) LOOP
  SELECT pg_get_functiondef(p.oid) INTO STRICT definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=r.name;
  patched:=replace(definition,r.old_guard,format('(%s AND private.system_override_guard(auth.uid(),%s,%L,%L))',r.old_guard,r.school_expression,r.module,r.action));
  IF patched=definition THEN RAISE EXCEPTION 'Authorization guard missing in %',r.name; END IF; EXECUTE patched;
 END LOOP;
 SELECT pg_get_functiondef('public.convert_admission_application(uuid,uuid)'::regprocedure) INTO definition;
 patched:=replace(definition,'public.can_manage_students(auth.uid(), app.school_id)','(public.can_manage_students(auth.uid(), app.school_id) AND private.system_override_guard(auth.uid(),app.school_id,''admissions'',''manage'') AND private.system_override_guard(auth.uid(),app.school_id,''students'',''create''))');
 IF patched=definition THEN RAISE EXCEPTION 'Conversion guard missing'; END IF; EXECUTE patched;
 SELECT pg_get_functiondef('private.custom_module_management_guard()'::regprocedure) INTO definition;
 patched:=replace(definition,'IF NOT system_manager AND requires_manage','IF requires_manage AND (NOT system_manager OR NOT private.system_override_guard(auth.uid(),OLD.school_id,module,''manage''))');
 IF patched=definition THEN RAISE EXCEPTION 'Management guard missing'; END IF; EXECUTE patched;
END $$;
CREATE OR REPLACE FUNCTION public.can_access_reports(_school_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT (private.has_system_school_role(_school_id) OR public.has_custom_module_permission(auth.uid(),_school_id,'reports','view')) AND private.system_override_guard(auth.uid(),_school_id,'reports','view');
$$;
COMMIT;